-- Additive migration. No existing trial or recruitment record is changed.
CREATE TABLE mi_settings (id TEXT PRIMARY KEY CHECK(id='workspace'), payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE mi_projects (id TEXT PRIMARY KEY, match_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, state TEXT NOT NULL, region TEXT NOT NULL, stage TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX mi_projects_filters ON mi_projects(state,stage,updated_at);
CREATE TABLE mi_sectors (id TEXT PRIMARY KEY, name TEXT NOT NULL);
INSERT INTO mi_sectors VALUES ('engineering','Renewable Energy Engineering'),('solar','Solar'),('hydro','Hydro'),('wind','Wind'),('waste','Waste to Energy'),('storage','Energy Storage'),('transmission','Transmission'),('ev','Electric Vehicles');
CREATE TABLE mi_project_sectors (project_id TEXT NOT NULL REFERENCES mi_projects(id), sector_id TEXT NOT NULL REFERENCES mi_sectors(id), PRIMARY KEY(project_id,sector_id));
CREATE TABLE mi_organisations (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalised_name TEXT NOT NULL UNIQUE, website TEXT, organisation_type TEXT, public_contact_details TEXT);
CREATE TABLE mi_sources (id TEXT PRIMARY KEY, source_url TEXT NOT NULL UNIQUE, title TEXT NOT NULL, publisher TEXT NOT NULL, publication_date TEXT, retrieved_at TEXT NOT NULL, source_type TEXT NOT NULL, reliability TEXT NOT NULL, checked_at TEXT, http_status INTEGER);
CREATE TABLE mi_claims (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES mi_projects(id), claim_key TEXT NOT NULL UNIQUE, statement TEXT NOT NULL, kind TEXT NOT NULL, confidence TEXT NOT NULL, reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE mi_claim_sources (claim_id TEXT NOT NULL REFERENCES mi_claims(id), source_id TEXT NOT NULL REFERENCES mi_sources(id), excerpt TEXT NOT NULL, PRIMARY KEY(claim_id,source_id));
CREATE TABLE mi_project_organisations (project_id TEXT NOT NULL REFERENCES mi_projects(id), organisation_id TEXT NOT NULL REFERENCES mi_organisations(id), relationship_type TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES mi_claims(id), PRIMARY KEY(project_id,organisation_id,relationship_type));
CREATE TABLE mi_project_events (id TEXT PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES mi_projects(id), event_type TEXT NOT NULL, event_date TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER mi_events_no_update BEFORE UPDATE ON mi_project_events BEGIN SELECT RAISE(ABORT,'Project history is immutable'); END;
CREATE TRIGGER mi_events_no_delete BEFORE DELETE ON mi_project_events BEGIN SELECT RAISE(ABORT,'Project history is immutable'); END;
CREATE TABLE mi_leads (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES mi_projects(id), organisation_id TEXT NOT NULL REFERENCES mi_organisations(id), score INTEGER NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), status TEXT NOT NULL DEFAULT 'New', owner_id TEXT REFERENCES users(id), follow_up TEXT, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, UNIQUE(project_id,organisation_id));
CREATE INDEX mi_leads_priority ON mi_leads(status,score DESC);
CREATE TABLE mi_research_jobs (id TEXT PRIMARY KEY, run_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', model_id TEXT, reasoning_effort TEXT, response_id TEXT, result TEXT, error TEXT, attempts INTEGER NOT NULL DEFAULT 0, due_at TEXT NOT NULL, lease_until TEXT, lease_token TEXT, reserved_usd REAL NOT NULL DEFAULT 0, budget_month TEXT, created_at TEXT NOT NULL, completed_at TEXT);
CREATE INDEX mi_jobs_due ON mi_research_jobs(status,due_at);
CREATE TABLE mi_budgets (month TEXT PRIMARY KEY, spent_usd REAL NOT NULL DEFAULT 0, reserved_usd REAL NOT NULL DEFAULT 0, cap_usd REAL NOT NULL CHECK(cap_usd>=0));
CREATE TABLE mi_api_usage (job_id TEXT PRIMARY KEY REFERENCES mi_research_jobs(id), model_id TEXT NOT NULL, input_tokens INTEGER NOT NULL, cached_input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, reasoning_tokens INTEGER NOT NULL, tool_calls INTEGER NOT NULL, estimated_cost_usd REAL NOT NULL, billed_cost_usd REAL, recorded_at TEXT NOT NULL);
CREATE TABLE mi_reports (id TEXT PRIMARY KEY, period_start TEXT NOT NULL, period_end TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, html TEXT NOT NULL, validation TEXT NOT NULL, approved_by TEXT REFERENCES users(id), approved_at TEXT, created_at TEXT NOT NULL, UNIQUE(period_start,period_end));
CREATE TABLE mi_subscriptions (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, sectors TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, test_only INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE mi_email_deliveries (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES mi_reports(id), recipient_id TEXT NOT NULL REFERENCES mi_subscriptions(id), status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, provider_id TEXT, error TEXT, due_at TEXT NOT NULL, delivered_at TEXT, UNIQUE(report_id,recipient_id));
CREATE TABLE mi_audit (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE mi_alerts (id TEXT PRIMARY KEY, alert_key TEXT NOT NULL UNIQUE, severity TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, resolved_at TEXT);
